-- Mộc Inventory: PostgreSQL / Supabase schema
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE units (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(50) NOT NULL UNIQUE, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE ingredients (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(50) UNIQUE NOT NULL, name VARCHAR(100) NOT NULL, category VARCHAR(50) NOT NULL, base_unit_id UUID REFERENCES units(id), cost_price NUMERIC(12,2) DEFAULT 0, min_stock NUMERIC(10,2) DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE prep_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(50) UNIQUE NOT NULL, name VARCHAR(100) NOT NULL, unit_id UUID REFERENCES units(id), shelf_life_hours INT DEFAULT 24, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE prep_recipe_details (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), prep_item_id UUID REFERENCES prep_items(id) ON DELETE CASCADE, ingredient_id UUID REFERENCES ingredients(id), quantity NUMERIC(10,2) NOT NULL CHECK(quantity>0));
CREATE TABLE pos_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), pos_code VARCHAR(100) NOT NULL UNIQUE, pos_name VARCHAR(150) NOT NULL, size VARCHAR(20), created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE pos_item_bom (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), pos_item_id UUID REFERENCES pos_items(id) ON DELETE CASCADE, ingredient_id UUID REFERENCES ingredients(id), prep_item_id UUID REFERENCES prep_items(id), quantity NUMERIC(10,2) NOT NULL CHECK(quantity>0), CONSTRAINT chk_target_type CHECK ((ingredient_id IS NOT NULL AND prep_item_id IS NULL) OR (ingredient_id IS NULL AND prep_item_id IS NOT NULL)));
CREATE TABLE inventory_balance (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), item_type VARCHAR(20) NOT NULL CHECK(item_type IN ('RAW','PREP')), ingredient_id UUID REFERENCES ingredients(id), prep_item_id UUID REFERENCES prep_items(id), quantity NUMERIC(12,2) NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ DEFAULT NOW(), CONSTRAINT chk_balance_target CHECK ((item_type='RAW' AND ingredient_id IS NOT NULL AND prep_item_id IS NULL) OR (item_type='PREP' AND prep_item_id IS NOT NULL AND ingredient_id IS NULL)), CONSTRAINT uq_balance_raw UNIQUE(ingredient_id), CONSTRAINT uq_balance_prep UNIQUE(prep_item_id));
CREATE TABLE stock_ins (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(50) UNIQUE NOT NULL, supplier_name VARCHAR(100), total_amount NUMERIC(12,2) DEFAULT 0, note TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE stock_in_details (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), stock_in_id UUID REFERENCES stock_ins(id) ON DELETE CASCADE, ingredient_id UUID REFERENCES ingredients(id), quantity NUMERIC(10,2) NOT NULL CHECK(quantity>0), unit_price NUMERIC(12,2) NOT NULL CHECK(unit_price>=0));
CREATE TABLE prep_batches (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), prep_item_id UUID REFERENCES prep_items(id), output_quantity NUMERIC(10,2) NOT NULL CHECK(output_quantity>0), created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE wastage_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), item_type VARCHAR(20) NOT NULL CHECK(item_type IN ('RAW','PREP')), ingredient_id UUID REFERENCES ingredients(id), prep_item_id UUID REFERENCES prep_items(id), quantity NUMERIC(10,2) NOT NULL CHECK(quantity>0), reason VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW(), CONSTRAINT chk_wastage_target CHECK ((item_type='RAW' AND ingredient_id IS NOT NULL AND prep_item_id IS NULL) OR (item_type='PREP' AND prep_item_id IS NOT NULL AND ingredient_id IS NULL)));
CREATE TABLE pos_sales_imports (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), filename VARCHAR(255) NOT NULL, session_date DATE NOT NULL, total_orders INT DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE pos_sales_details (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), import_id UUID REFERENCES pos_sales_imports(id) ON DELETE CASCADE, pos_item_id UUID REFERENCES pos_items(id), quantity_sold INT NOT NULL CHECK(quantity_sold>=0));
CREATE TABLE inventory_audits (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), audit_date TIMESTAMPTZ DEFAULT NOW(), note TEXT);
CREATE TABLE inventory_audit_details (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), audit_id UUID REFERENCES inventory_audits(id) ON DELETE CASCADE, item_type VARCHAR(20) NOT NULL CHECK(item_type IN ('RAW','PREP')), ingredient_id UUID REFERENCES ingredients(id), prep_item_id UUID REFERENCES prep_items(id), system_qty NUMERIC(12,2) NOT NULL, actual_qty NUMERIC(12,2) NOT NULL, variance_qty NUMERIC(12,2) NOT NULL, CONSTRAINT chk_audit_target CHECK ((item_type='RAW' AND ingredient_id IS NOT NULL AND prep_item_id IS NULL) OR (item_type='PREP' AND prep_item_id IS NOT NULL AND ingredient_id IS NULL)));
CREATE INDEX idx_stock_ins_created_at ON stock_ins(created_at);
CREATE INDEX idx_prep_batches_created_at ON prep_batches(created_at);
CREATE INDEX idx_wastage_logs_created_at ON wastage_logs(created_at);
CREATE INDEX idx_pos_sales_imports_session_date ON pos_sales_imports(session_date);
CREATE INDEX idx_inventory_audits_audit_date ON inventory_audits(audit_date);
